@startuml

class MovieShop {
  + listMovies()
  + order()
  + subscribe()
}

class User {
  + name
  + surname
}

class Subscriber {
  + card
}

class Card {
  + credit
}

class Order {
  + date
}

class Movie {
  + title
}

class Rent {
  + date
}

class Buy {
  + date
}

User <|-- Subscriber
User "1" -- "*" Order : places
User "1" -- "*" Rent : performs
User "1" -- "*" Buy : performs
Subscriber "1" -- "1" Card : has
Card "1" -- "*" Rent : used for
MovieShop "1" -- "*" Movie : catalogues
MovieShop "1" -- "*" Order : handles
MovieShop "1" -- "*" Buy : handles
Order "*" -- "1" Movie : for
Rent "*" -- "1" Movie : for
Buy "*" -- "1" Movie : for

@enduml

